"""Slash-command handler for state-seed."""
from __future__ import annotations

from .result_nodes import make_result_node
from .state_step import seed_state_turn


def handle_state_seed_commands(
    command: str,
    args: list[str],
    *,
    step_mod: object,
    context: object,
) -> list[dict] | None:
    """Handle the /state-seed slash command.

    Args:
        command: The command name (without leading slash).
        args: The arguments to the command.
        step_mod: The step module (unused).
        context: The step context (unused).

    Returns:
        A list of result nodes if the command was handled, otherwise None.
    """
    if command != "state-seed":
        return None

    # Parse arguments: optional format
    fmt = "yaml"
    if len(args) > 0:
        fmt = args[0]

    try:
        content = seed_state_turn(format=fmt)
    except Exception as e:
        content = f"Error seeding state: {e}"

    return [
        make_result_node(
            content,
            origin_role="assistant",
            origin_kind="slash_command",
        )
    ]
